import { BrowserProvider } from 'ethers';

const TRACKING_HEAD_TIMEOUT_MS = 3_000;
const STOP_TRACKING_CODES = new Set(['CANCELLED', 'BAD_DATA', 'NETWORK_ERROR', 'UNSUPPORTED_OPERATION']);

// Ethers' JsonRpcSigner.sendTransaction awaits this read before it even asks
// the wallet to open. It is only the starting block for replacement tracking;
// run it beside the approval instead. A failed read must not fail an approval.
function trackingHead(provider) {
  return new Promise(resolve => {
    const timer = setTimeout(() => resolve(null), TRACKING_HEAD_TIMEOUT_MS);
    timer?.unref?.();
    Promise.resolve().then(() => provider.getBlockNumber()).then(
      block => {
        clearTimeout(timer);
        resolve(Number.isSafeInteger(block) && block >= 0 ? block : null);
      },
      () => { clearTimeout(timer); resolve(null); },
    );
  });
}

/**
 * Send a prepared wallet transaction without waiting for a tracking RPC.
 * Callers still own account/network checks, fees and an explicit gas limit.
 * sendUncheckedTransaction retains ethers' from/to validation and RPC encoding.
 * Return a real TransactionResponse, so Contract wrappers, receipts and wallet
 * speed-ups continue to work with ethers' normal transaction APIs.
 */
export async function sendWalletTransaction(signer, request) {
  if (!(signer?.provider instanceof BrowserProvider)
    || typeof signer.sendUncheckedTransaction !== 'function') {
    return signer.sendTransaction(request);
  }

  const provider = signer.provider;
  const head = trackingHead(provider);
  const hash = await signer.sendUncheckedTransaction(request);
  // From here onward, never send again. The wallet has returned a broadcast
  // hash, even if its RPC has not indexed that transaction yet.
  let invalids = 0;
  let attempt = 0;
  for (;;) {
    try {
      const tx = await provider.getTransaction(hash);
      if (tx != null) {
        const block = await head;
        return block == null ? tx : tx.replaceableTransaction(block);
      }
    } catch (cause) {
      if (cause?.code === 'INVALID_ARGUMENT') invalids += 1;
      if (STOP_TRACKING_CODES.has(cause?.code) || invalids > 10) {
        const error = new Error('Transaction submitted. Check wallet Activity for confirmation before retrying.', { cause });
        error.code = 'TRANSACTION_TRACKING_FAILED';
        error.transactionHash = hash;
        throw error;
      }
      // Match ethers' propagation retry behavior for temporary RPC failures.
    }
    const delay = attempt++ === 0 ? 100 : attempt === 2 ? 1_000 : 4_000;
    await new Promise(resolve => setTimeout(resolve, delay));
  }
}
